-- Foundation Studio · Snowflake execution SQL
-- foundation:stage 2
CREATE OR REPLACE TABLE OGFS_DEMO.GOLD.fact_lab_sample AS SELECT b.lab_sample_key,d1.material_sk AS material_sk,d2.test_method_sk AS test_method_sk,b.site_key,b.business_line_key,b.date_key,b.turnaround_days,b.sample_status,b.source_system_count FROM (SELECT lab_sample_key,material_key,test_method_key,'SITE_'||UPPER(site_code) site_key,CASE LOWER(business_line) WHEN 'lubricants' THEN 'BIZ_LUBRICANTS' WHEN 'fuels' THEN 'BIZ_FUELS' WHEN 'chemicals' THEN 'BIZ_CHEMICALS' END business_line_key,TO_NUMBER(TO_CHAR(TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(completion_date)),'YYYYMMDD')) date_key,DATEDIFF(day,TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(requested_date)),TRY_TO_TIMESTAMP_NTZ(TO_VARCHAR(completion_date))) turnaround_days,sample_status,source_system_count,TRY_TO_TIMESTAMP_TZ(completion_date) _event_time FROM OGFS_DEMO.SILVER.conformed_lab_sample) b LEFT JOIN OGFS_DEMO.GOLD.dim_material d1 ON d1.material_key=b.material_key AND b._event_time >= d1.valid_from AND b._event_time < d1.valid_to LEFT JOIN OGFS_DEMO.GOLD.dim_test_method d2 ON d2.test_method_key=b.test_method_key AND b._event_time >= d2.valid_from AND b._event_time < d2.valid_to;
